void __fastcall DrawLine(int32_t nXStart, int32_t nYStart, int32_t nXEnd, int32_t nYEnd, BYTE dwColor, BYTE nAlpha) {
    int nStepsRemaining;
    int nErrorSpill;
    int nDeltaX = nXEnd - nXStart;
    int nDeltaY = nYEnd - nYStart;
    if (nDeltaX < 0) {
      nXEnd = -1;
      nDeltaX = -nDeltaX;
    } else {
      nXEnd = 1;
    }
    if (nDeltaY < 0) {
      nDeltaY = -nDeltaY;
      nYEnd = -1;
    } else {
      nYEnd = 1;
    }
    if (nXStart >= 0 && nXStart < RENDERER_nWindowWidth && nYStart >= 0 && nYStart < RENDERER_nWindowHeight) {
      gpRenderBackBufferBits[nXStart + RENDERER_nWindowWidth * nYStart] = dwColor;
    }

    int nError = 0;
    if (nDeltaX < nDeltaY) {
      nStepsRemaining = nDeltaY;
      if (nDeltaY > 0) {
        do {
          nYStart += nYEnd;
          nError += nDeltaX;
          if (nError > nDeltaY) {
            nXStart += nXEnd;
            nError -= nDeltaY;
          }
          if (nXStart >= 0 && nXStart < RENDERER_nWindowWidth && nYStart >= 0 && nYStart < RENDERER_nWindowHeight) {
            gpRenderBackBufferBits[nXStart + RENDERER_nWindowWidth * nYStart] = dwColor;
          }

          nStepsRemaining--;
        } while (nStepsRemaining);

        return;
      }
    } else {
      nStepsRemaining = nDeltaX;
      if (nDeltaX > 0) {
        do {
          nXStart += nXEnd;
          nError += nDeltaY;
          if (nError > nDeltaX) {
            nYStart += nYEnd;
            nError -= nDeltaX;
          }
          if (nXStart >= 0 && nXStart < RENDERER_nWindowWidth && nYStart >= 0 && nYStart < RENDERER_nWindowHeight) {
            gpRenderBackBufferBits[nXStart + RENDERER_nWindowWidth * nYStart] = dwColor;
          }

          nStepsRemaining--;
        } while (nStepsRemaining);
      }
    }
}

