void __fastcall ClearScreen(BOOL bPartial) {
    DDBLTFX ddBltFx;
    ddBltFx.dwSize = 100;
    memset(&ddBltFx.dwDDFX, 0, sizeof(ddBltFx) - sizeof(ddBltFx.dwSize));
    ddBltFx.dwFillColor = 0;
    if (!pDirectDrawSurface) {
      return;
    }

    HRESULT nDDrawResult = pDirectDrawSurface->lpVtbl->Blt(pDirectDrawSurface, nullptr, nullptr, nullptr, 0x400, &ddBltFx);
    if (!nDDrawResult) {
      return;
    }
    if (nDDrawResult == -0x7789fe52) {
      if (bPartial) {
        memset(gpRenderBackBufferBits, 0, (RENDERER_nWindowHeight - 0x2f) * RENDERER_nWindowWidth);
        return;
      }

      memset(gpRenderBackBufferBits, 0, RENDERER_nWindowHeight * RENDERER_nWindowWidth);
      return;
    }

    DirectDrawErrorHandler("Blit (screen clear) failed!", nDDrawResult);
}

